// Standalone design interactions. No API, model calls or execution.
const $ = selector => document.querySelector(selector);
const state = {companionMode:'write',view:'home',homeTab:'overview',caseName:'Data Center Energy Hub',source:'eh_datacenter',selected:['capacity','reliability','infrastructure','gridcode','controls'],step:'capacity',values:{},conditions:{},planning:{},scopes:{},expertPanel:'Network & assets',dark:true,reliabilityAim:'tradeoff'};
const baseModules = [
 {id:'capacity',icon:'▥',name:'Capacity expansion',short:'Capacity design',description:'Size energy assets across supported carriers, with economic dispatch, investment costs and operating costs included in the same planning study.',result:'Capacity, dispatch & economics',prerequisite:'Demand, profiles, costs and build limits',status:'Includes dispatch & economics',inputs:['Peak electric demand','Other carrier demand basis'],defaults:['50','Heat / hydrogen demand profiles'],units:['MW',''],advanced:['Battery build limit','Discount rate'],advancedDefaults:['25','5'],advancedUnits:['MW','%']},
 {id:'reliability',icon:'◈',name:'Reliability assessment',short:'Reliability',description:'Compare cost against adequacy and continuity requirements, with explicit outage assumptions and method limits.',result:'Adequacy & failure modes',prerequisite:'Critical demand, outage assumptions and method inputs',status:'Optional · cost–reliability assessment',inputs:['Critical demand','Adequacy target'],defaults:['30','3'],units:['MW','h/year'],advanced:['Value of lost load','Study seed'],advancedDefaults:['10000','42'],advancedUnits:['€/MWh','']},
 {id:'controls',icon:'≋',name:'Control strategies',short:'Controls',description:'Configure supported study controls and review their assumptions and constraints.',result:'Supported control settings & checks',prerequisite:'Eligible assets and a supported control adapter',status:'Study-specific controls only',inputs:['Control objective','Selected equipment'],defaults:['Study-specific control objective','Compatible assets only'],units:['',''],advanced:['Control setting','Setting unit'],advancedDefaults:['Defined by native schema','Defined by native schema'],advancedUnits:['','']},
 {id:'dynamics',icon:'∿',name:'Frequency & time domain',short:'Dynamics',description:'Connect eligible screening and prepare detailed simulation in a supported simulator.',result:'Screening & simulator evidence',prerequisite:'Solved source, dynamic data and compatible simulator',status:'External simulator / setup',inputs:['Study objective','Source basis'],defaults:['Frequency screening or detailed dynamics','Saved solved source'],units:['',''],advanced:['Disturbance size','Study duration'],advancedDefaults:['10','20'],advancedUnits:['MW','s']},
 {id:'process',icon:'⌘',name:'Detailed process modeling',short:'Processes',description:'Couple supported production throughput, energy use and product inventory to the energy plan; keep fixed process-unit sizes distinct from optimized energy capacities.',result:'Process throughput, inventory & energy coupling',prerequisite:'Supported process schema, product units, production targets and energy-coupling data',status:'Optional · coupled throughput & inventory',inputs:['Production target basis','Energy coupling'],defaults:['Product-specific target and units','Supported process model'],units:['',''],advanced:['Lost-production value','Process-unit sizing'],advancedDefaults:['Required by product and money basis','Fixed client input unless adapter explicitly supports sizing'],advancedUnits:['','']},
 {id:'infrastructure',icon:'♧',name:'Electrical infrastructure sizing',short:'Grid infrastructure',description:'Design and parameterize supported transformers, cables and reactive compensation around the energy plan and electrical limits.',result:'Electrical design & equipment basis',prerequisite:'Topology, equipment data, critical operating points and supported electrical sizing model',status:'Study-specific equipment design',inputs:['Design basis','Equipment scope'],defaults:['Critical operating points','Transformers, connections and compensation'],units:['',''],advanced:['Equipment rating basis','Design margin'],advancedDefaults:['Native equipment schema','Explicit engineering assumption'],advancedUnits:['','']},
 {id:'gridcode',icon:'◇',name:'Grid-code assessment',short:'Grid-code checks',description:'Include the load-flow calculations needed for supported grid-code requirements, then report loading, voltage and the assessed clauses. Dynamic requirements remain a separate validation.',result:'Load flow & grid-code assessment',prerequisite:'Applicable code/profile version, PCC definition, valid electrical results and method limits',status:'Includes required load-flow checks',inputs:['Applicable grid-code profile','Connection point','Operating-point source'],defaults:['Explicit jurisdiction and profile version','Model PCC','Compatible saved or selected-run source'],units:['','',''],advanced:['Evidence basis','Dynamic requirements'],advancedDefaults:['Exact supported clauses and method','Unassessed until separate validated study'],advancedUnits:['','']},
 {id:'contingencies',icon:'◈',name:'Contingencies & resilience',short:'Contingencies',description:'Assess supported equipment outages and redundancy needs; keep deterministic network security separate from probabilistic adequacy.',result:'Contingency screening & resilience gaps',prerequisite:'Credible outage cases, intact equipment data and supported source/study method',status:'Explicit cases & method required',inputs:['Contingency scope','Operating basis'],defaults:['Explicit supported N-1 / screening cases','Compatible saved source'],units:['',''],advanced:['Equipment outage data','Acceptance criteria'],advancedDefaults:['Required by selected method','Explicit network limits'],advancedUnits:['','']},
 {id:'islanding',icon:'⌁',name:'Islanding & recovery',short:'Island operation',description:'Assess supported island-operation assumptions, reserve and recovery requirements; detailed transition behavior needs dynamic validation.',result:'Island-operation screening & recovery requirements',prerequisite:'Grid-forming capability, reserve, protection assumptions and supported island/dynamic model',status:'Screening; transitions need validation',inputs:['Operating mode','Disturbance scenario'],defaults:['Grid connected / islanded / transition','Explicit disturbance and recovery basis'],units:['',''],advanced:['Reserve basis','Recovery criteria'],advancedDefaults:['Supported control and equipment model','Explicit resynchronization / restart criteria'],advancedUnits:['','']},
];
const modules=sections.flatMap(section=>section.members.map(id=>baseModules.find(module=>module.id===id)));
// Catalogue and scenario descriptions supplied by the owner; readiness is not runtime certification.
const demos = [
 {id:'eh_datacenter',name:'Data Center Energy Hub',title:'Data centers',category:'DIGITAL INFRASTRUCTURE',note:'50 MW campus. Weak 40 MW grid connection, UPS battery, gas gensets and rooftop PV.',detail:'Gensets and batteries are expansion candidates. Optional AI-training profile and dynamic-load envelope are referenced in DC 01 / #421.',art:'datacenter',stagedId:'eh_datacenter_staged',presetNote:'Suggested: capacity, reliability, electrical design, grid-code/load-flow checks and controls. Detailed eligibility still needs to be checked.',suggested:['capacity','reliability','infrastructure','gridcode','controls']},
 {id:'eh_microgrid',name:'Island Microgrid',title:'Island microgrids',category:'RESILIENT ENERGY',note:'Operate without a 20 MW subsea tie. Renewables, a battery, three diesels and critical hospital demand.',detail:'PV, wind, battery and diesel supply serve a critical hospital feeder and residential demand.',art:'microgrid',stagedId:'eh_microgrid_staged',presetNote:'Suggested: capacity, reliability, grid-code/load-flow checks, controls and island operation. Source and control setup are prerequisites.',suggested:['capacity','reliability','gridcode','controls','islanding']},
 {id:'eh_h2_hub',name:'Industrial Hydrogen Hub',title:'Hydrogen production',category:'INDUSTRIAL DECARBONIZATION',note:'120 MW wind, 80 MW PV and a 60 MW electrolyser. Couple energy supply and hydrogen production.',detail:'H₂ storage, fuel cell and site battery; 40 MW critical process load and 25 MW H₂ offtake. Keep hydrogen and electrical energy bases explicit.',art:'hydrogen',stagedId:'eh_h2_hub_staged',presetNote:'Suggested: capacity and detailed process modeling. Grid and control studies are optional when the project requires them; process setup must be verified.',suggested:['capacity','process']},
 {id:'eh_datacenter_staged',name:'Data Center Energy Hub (staged growth)',title:'Data centers',category:'STAGED DIGITAL INFRASTRUCTURE',note:'2027 → 2030 → 2035. IT demand grows 12 → 24 → 36 MW as the utility connection is energized in steps.',detail:'Plan what to build and when. Period-specific demand and connection limits must come from the native template, not inferred from the single-period peak.',art:'datacenter',variant:true,presetNote:'Staged growth: 2027, 2030 and 2035. Suggested: capacity, reliability, electrical design, grid-code/load-flow checks and controls. Native multi-period eligibility and source compatibility still need verification.',suggested:['capacity','reliability','infrastructure','gridcode','controls']},
 {id:'eh_microgrid_staged',name:'Island Microgrid (staged growth)',title:'Island microgrids',category:'STAGED RESILIENT ENERGY',note:'Plan island supply across 2027, 2030 and 2035.',detail:'Three-period growth of the island system. Use native period-specific inputs and investment constraints.',art:'microgrid',variant:true,presetNote:'Staged growth: 2027, 2030 and 2035. Suggested: capacity, reliability, grid-code/load-flow checks, controls and island operation. Source and control setup are prerequisites.',suggested:['capacity','reliability','gridcode','controls','islanding']},
 {id:'eh_h2_hub_staged',name:'H2 hub, staged growth',title:'Hydrogen production',category:'STAGED INDUSTRIAL DECARBONIZATION',note:'Plan the hydrogen hub across 2027, 2030 and 2035.',detail:'Three-period growth of the hydrogen hub. Product units and throughput assumptions remain bound to the native staged template.',art:'hydrogen',variant:true,presetNote:'Staged growth: 2027, 2030 and 2035. Suggested: capacity and detailed process modeling. Native process and multi-period setup must be verified.',suggested:['capacity','process']},
 {id:'concept_ammonia',name:'Ammonia plant (staged)',title:'Ammonia production',category:'GRID-TO-PROCESS · IN DEVELOPMENT',note:'Electricity and H₂ to NH₃. Staged production at 50, 100 and 150 t/day.',detail:'Owner-reported scope in #418; not merged. First grid-to-process template, ahead of mining.',art:'ammonia',planned:true,status:'IN DEVELOPMENT · #418',presetNote:'Workflow preview only — the staged ammonia template in #418 is not merged. Suggested draft: capacity and process modeling. Production targets are 50, 100 and 150 tonnes NH₃/day; native process integration and evidence are still required.',suggested:['capacity','process']},
 {id:'concept_mining',name:'Mining & minerals',title:'Mining & minerals',category:'ENERGY-INTENSIVE INDUSTRY · PLANNED',note:'Explore electrified operations, process demand and remote-site supply.',detail:'Planned after the ammonia grid-to-process template. No bundled mining backend template is established.',art:'mining',planned:true,status:'PLANNED · AFTER AMMONIA',presetNote:'Workflow preview only — mining has no bundled backend template yet. Model and process setup are required. Suggested draft: capacity and process modeling; add reliability or electrical/control studies when the site requires them.',suggested:['capacity','process']},
];
function industryPicture(demo){return `<img data-industry="${demo.art}" alt="" width="960" height="600">`;}
function sourceReadiness(){const example=demos.find(demo=>demo.id===state.source);return example?.planned?`<p class="source-readiness"><b>Workflow preview · template setup required.</b>${example.id==='concept_ammonia'?'Ammonia is in development in #418 and not merged.':'Mining is planned after ammonia, not a bundled or execution-ready model.'}</p>`:'';}
function planningDraft(){return state.planning[state.source]??{start:'2027',end:'2035',dates:''};}
function validPlanning(){const plan=planningDraft();if(!/^\d{4}$/.test(plan.start)||!/^\d{4}$/.test(plan.end)||Number(plan.start)<1900||Number(plan.end)>2200||Number(plan.start)>Number(plan.end))return false;if(!plan.dates.trim())return true;const dates=plan.dates.split(',').map(value=>value.trim());return dates.length<=32&&dates.every((value,index)=>/^\d{4}$/.test(value)&&Number(value)>=Number(plan.start)&&Number(value)<=Number(plan.end)&&(index===0||Number(value)>Number(dates[index-1])));}

function planningControls(){const plan=planningDraft();return `<section class="planning-controls"><div><h3>Planning period</h3><p>Choose the years for this example. No separate single-period or staged-growth mode.</p></div><div class="planning-fields"><label for="planning-start">Start year</label><input id="planning-start" data-planning="start" type="number" min="1900" max="2200" value="${escapeHtml(plan.start)}"><label for="planning-end">End year</label><input id="planning-end" data-planning="end" type="number" min="1900" max="2200" value="${escapeHtml(plan.end)}"></div><details><summary>Advanced planning dates</summary><label for="planning-dates">Investment dates (draft)</label><input id="planning-dates" data-planning="dates" value="${escapeHtml(plan.dates)}"><p>Native integration must validate dates, horizon, weights and available investment models. This preview creates no project or solve.</p></details><p id="planning-error" role="status">${validPlanning()?'':'Choose whole years from 1900 to 2200, with the end year at or after the start. Optional investment dates must be ordered, unique and within the period.'}</p></section>`;}
function scenarioContext(){const example=demos.find(demo=>demo.id===state.source);return example?`<div class="scenario-context"><b>${example.planned?'PROPOSED INDUSTRY EXAMPLE':'INTEGRATED PLANNING EXAMPLE'}</b><p>${escapeHtml(example.note)}</p><p>${escapeHtml(example.detail)}</p><p>Planning period: ${escapeHtml(planningDraft().start)}–${escapeHtml(planningDraft().end)} · draft, not a solved study.</p></div>`:'';}

function studyConditions(){const draft=state.conditions[state.source]??{stress:'baseline',shape:'template',annual:''};const options=(items,selected)=>items.map(([id,label])=>`<option value="${id}" ${id===selected?'selected':''}>${label}</option>`).join('');return `<section class="study-conditions"><h3>Study conditions</h3><p>Apply a stress week or a synthetic load shape to the chosen model. These are input options, not additional workflow sections.</p><div class="field-grid"><div class="condition-field"><label for="stress-week">Stress week</label><select id="stress-week" data-condition="stress">${options([['baseline','Template baseline'],['heatwave','Heatwave · cooling peak + PV derate'],['darkstill','Dark, still week · Dunkelflaute'],['lowwind','Low-wind week']],draft.stress)}</select></div><div class="condition-field"><label for="load-shape">Load shape</label><select id="load-shape" data-condition="shape">${options([['template','Template load profiles'],['office','Commercial office · synthetic'],['industrial','Two-shift industrial site · synthetic']],draft.shape)}</select></div><div class="condition-field"><label for="annual-energy">Annual energy for synthetic load (MWh)</label><input id="annual-energy" data-condition="annual" inputmode="decimal" type="number" min="0" value="${escapeHtml(draft.annual)}" ${draft.shape==='template'?'disabled':''}></div></div><p class="fine">Synthetic shapes are made up and scaled to the site’s annual MWh; they are not measured data. Stress settings need explicit native assumptions and source validation. Preview only — no profiles are generated or applied.</p></section>`;}

function selectedModules(){return modules.filter(module=>state.selected.includes(module.id));}
function stageList(){return [{id:'model',name:'Model & inputs'},...selectedModules().map(module=>({id:module.id,name:module.short})),{id:'review',name:'Review & run'},{id:'results',name:'Results & report'}];}
function activeModule(){return modules.find(module=>module.id===state.step);}
function stepName(){return stageList().find(step=>step.id===state.step)?.name??'Workflow setup';}
function ensureValidStep(){if(!stageList().some(step=>step.id===state.step))state.step='model';}
function modePill(){return `<div class="mode-pill" aria-label="Workspace mode"><button data-view="guided" class="${state.view==='guided'?'selected':''}" aria-pressed="${state.view==='guided'}">Guided</button><button data-view="expert" class="${state.view==='expert'?'selected':''}" aria-pressed="${state.view==='expert'}">Expert</button></div>`;}
function homeSidebar(){return `<div><p class="nav-label">WORKSPACE</p><nav class="home-nav" aria-label="Home sections">${[['overview','◫','Overview'],['examples','◇','Examples'],['projects','▤','My projects']].map(([id,icon,name])=>`<button class="nav-item ${state.homeTab===id?'active':''}" data-home-tab="${id}" ${state.homeTab===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${name}</button>`).join('')}</nav></div><div class="nav-foot"><p class="eyebrow">ONE CONNECTED STUDY</p><p class="fine">Choose the analyses you need. Move into Expert or ask GridSpine for detailed help at any point.</p></div>`;}
function demoCard(demo){return `<button class="demo" data-demo="${demo.id}"><div class="demo-art">${industryPicture(demo)}<span class="media-badge">${demo.status??'CONFIGURABLE PLANNING HORIZON'}</span></div><div class="demo-body"><span class="demo-category">${demo.category}</span><h3>${demo.title}</h3><p>${demo.note}</p><span class="demo-link">${demo.planned?'Preview workflow':'Plan this example'} <span aria-hidden="true">→</span></span></div></button>`;}

function exampleLibrary(){return `<div class="demo-grid example-library">${demos.filter(demo=>!demo.variant&&!demo.planned).map(demoCard).join('')}</div><div class="section-heading upcoming-heading"><div><h2>Next industry examples</h2><p>Design previews · backend templates are still in development or planned.</p></div></div><div class="demo-grid upcoming-grid">${demos.filter(demo=>demo.planned).map(demoCard).join('')}</div>`;}

function homeMain(){
 if(state.homeTab==='projects')return `<span class="eyebrow">YOUR WORKSPACE</span><div class="title-row"><div><h1>Your projects.</h1><p>Return to your model and its connected workflow.</p></div></div><p class="fine">Illustrative projects · no account data loaded</p><div class="project-list" style="margin-top:20px">${demos.filter(demo=>!demo.variant&&!demo.planned).map(demo=>`<div class="project-row"><div><h3>${demo.name}</h3><p>Sample workflow · not run</p></div><button class="secondary" data-resume="${demo.id}">Resume project →</button></div>`).join('')}</div>`;
 const examplesOnly=state.homeTab==='examples';
 return `<span class="eyebrow">FROM MODEL TO DECISION</span><div class="title-row"><div><h1>${examplesOnly?'Choose your starting model.':'Start a guided workflow.'}</h1><p>Start with an example or build your own model. Then choose activities within energy planning, grid design and dynamic validation.</p></div><span class="tag">Your scope. Your workflow.</span></div>${examplesOnly?'':`<section class="resume" aria-label="Resume project"><div class="resume-content"><div class="resume-icon" aria-hidden="true">⌁</div><div><h3><small>RESUME</small>Data Center Energy Hub</h3><p>Energy & system planning · illustrative project</p></div></div><button class="primary" data-resume="eh_datacenter">Resume workflow →</button></section>`}<section class="own-model"><div class="own-symbol" aria-hidden="true">＋</div><div><h2>Build your own workflow</h2><p>Start with a generic model, import your network, or choose an example later.</p></div><button class="primary" data-generic>Configure workflow →</button></section><section aria-labelledby="examples-title"><div class="section-heading"><div><h2 id="examples-title">${examplesOnly?'Example models':'Or start with an example'}</h2><p>Industry starting points. Editable scope, connected analyses.</p></div>${examplesOnly?'':'<button class="text-btn" data-home-tab="examples">All examples →</button>'}</div>${exampleLibrary()}</section><section class="expert-entry"><div><h3>Prefer to work directly with the model?</h3><p>Use the complete Expert workspace for detailed parameterization.</p></div><button class="secondary" data-view="expert">Enter Expert →</button></section>`;
}
function builderSidebar(){return `<div class="project-summary"><p>New guided workflow</p><span class="tag">Choose your scope</span></div><nav class="builder-rail" aria-label="Workflow setup"><div class="step"><b>1</b><span>Starting model<small>Example or your own</small></span></div><div class="step active" aria-current="step"><b>2</b><span>Connect analyses<small>Include only what you need</small></span></div><div class="step"><b>3</b><span>Guided workspace<small>Configure, review and run</small></span></div></nav><div class="nav-foot"><p class="fine">The selection is a plan. It does not run a calculation or approve model changes.</p><button class="nav-item" data-view="home">← Workspace overview</button></div>`;}
function sourceOptions(){return `<option value="generic" ${state.source==='generic'?'selected':''}>Your own model / import</option>${demos.filter(demo=>!demo.variant).map(demo=>`<option value="${demo.id}" ${state.source===demo.id?'selected':''}>${demo.name}${demo.planned?' · workflow preview':''}</option>`).join('')}`;}
function connectionNotes(){
 const ids=state.selected,notes=[];
 if(ids.includes('capacity'))notes.push('Capacity planning includes economic dispatch and investment/operating costs. There are no separate dispatch or economics workflow choices.');
 if(ids.includes('capacity')&&!ids.includes('gridcode'))notes.push('Grid-code assessment and its load-flow checks are outside this scope.');
 if(ids.includes('gridcode'))notes.push('Grid-code assessment includes required load-flow calculations. It needs a compatible operating source; capacity expansion is not required when an existing source is suitable.');
 if(ids.includes('reliability'))notes.push('Reliability is an optional assessment with explicit demand, outage and method inputs. Grid-code/load-flow work is not automatically required.');
 else if(ids.includes('capacity'))notes.push('Reliability assessment is not selected. Economic planning alone does not establish a reliability target.');
 if(ids.includes('process'))notes.push('Detailed process coupling uses supported product units and fixed process-unit sizing rules; it does not silently optimize every process-unit size.');
 if(ids.includes('gridcode'))notes.push('Steady-state grid-code screening is not dynamic validation or a compliance certificate.');
 if(ids.includes('islanding'))notes.push('Islanded adequacy does not prove a stable islanding transition or successful recovery.');
 if(ids.includes('controls')||ids.includes('dynamics'))notes.push('Control and dynamic studies need eligible models; detailed time-domain work may require an external simulator.');
 return notes.length?notes:['Choose at least one activity. Calculations within a selected activity remain subject to native checks and approvals.'];
}
function guidedSidebar(){return `<div class="project-summary"><p>${escapeHtml(state.caseName)}</p><span class="tag">${selectedModules().length} connected analyses</span></div><div><p class="nav-label">YOUR WORKFLOW</p><nav class="step-list" aria-label="Workflow steps">${groupedStageRail()}</nav></div><div class="nav-foot"><button class="nav-item" data-view="builder">Edit workflow composition</button><button class="nav-item" data-view="home">← Workspace overview</button></div>`;}
function field(label,value,unit,id){const saved=state.values[`${state.source}:${state.step}`]?.[id]??value;return `<label>${label}<span class="unit"><input data-field="${id}" value="${escapeHtml(saved)}" ${unit?'type="number" min="0" step="any"':'type="text"'}>${unit?`<span>${unit}</span>`:''}</span></label>`;}
function nextStage(){const stages=stageList();return stages[Math.min(stages.findIndex(step=>step.id===state.step)+1,stages.length-1)].id;}
function stageInputs(module){const example=demos.find(demo=>demo.id===state.source);if(module.id==='capacity'&&example?.planned)module={...module,inputs:['Demand profile basis','Native template readiness'],defaults:['Project-specific demand required','Template setup required — preview only'],units:['','']};if(module.id==='capacity'&&example?.variant)module={...module,inputs:['Investment periods','Period-specific demand basis','Grid connection schedule'],defaults:['2027 / 2030 / 2035',state.source==='eh_datacenter_staged'?'IT load: 12 / 24 / 36 MW':'Native period-specific load profiles','Native period-specific connection limits'],units:['','','']};return `<form id="stage-form" class="form-card"><h2>${module.name}</h2><p class="muted">${module.description}</p>${module.id==='reliability'?`<div class="reliability-stage-control">${reliabilityObjectiveControl()}</div>`:''}${bundledActivities(module)}<div class="field-grid">${module.inputs.map((label,index)=>field(label,module.defaults[index],module.units[index],`input-${index}`)).join('')}</div><p class="form-note">Required basis: ${module.prerequisite.toLowerCase()}. Source compatibility is not checked in this visual preview.</p>${activityLimitations(module)}${module.id==='controls'||module.id==='dynamics'?`<div class="state-note">${module.id==='controls'?'Generic control editing is not yet available. Only supported study-specific settings can be offered by the product.':'Specialized screening is different from full time-domain simulation. External simulator configuration and exact source evidence may be required.'}</div>`:''}<details class="advanced"><summary>Advanced for this stage</summary><div class="field-grid">${module.advanced.map((label,index)=>field(label,module.advancedDefaults[index],module.advancedUnits[index],`advanced-${index}`)).join('')}</div><p class="fine">Fields and defaults here are illustrative. Production settings come from the model schema.</p></details><div class="step-footer"><button class="text-btn" type="button" data-open-chat="Help me parameterize the ${module.name} stage. Show proposed changes before applying them.">Help parameterize this stage →</button><button type="submit" class="primary">Continue →</button></div></form>`;}
function guidedMain(){
 ensureValidStep();const module=activeModule();let content;
 if(module)content=stageInputs(module);
 else if(state.step==='model')content=`<section class="form-card"><h2>Your model, shared across the workflow</h2><p class="muted">${escapeHtml(state.caseName)} · illustrative starting source</p>${sourceReadiness()}${scenarioContext()}<p class="form-note">Set the model, shared time horizon and source once. Each selected analysis adds only the settings it needs.</p><div class="domain-list"><div class="domain-item"><h3>Model & parameters</h3><p>Use a bundled example, import a model, or build one with the native editors.</p><button class="text-btn" data-notice="The production workflow uses the existing model/import wizard. No file is uploaded here.">Set up model →</button></div><div class="domain-item"><h3>Existing result source</h3><p>Use compatible saved evidence where allowed. Planning is optional; a later stage must not silently start a new solve.</p></div></div>${studyConditions()}<div class="step-footer"><button class="text-btn" data-view="builder">Edit selected analyses</button><button class="primary" data-step="${nextStage()}">Continue to first analysis →</button></div></section>`;
 else if(state.step==='review')content=`<section class="form-card"><h2>Review the connected study</h2><p class="muted">${selectedModules().map(module=>module.short).join(' → ')}</p><div class="state-note">No model, inputs, source compatibility or simulator has been checked in this preview. In the product, each selected stage needs native validation and applicable approvals.</div><ul class="check-list" style="margin-top:18px">${selectedModules().map(module=>`<li>○ ${module.name} — validation not performed</li>`).join('')}</ul><p class="form-note">Each calculation keeps its own status, evidence and admission. Skipped or failed stages cannot certify dependent stages. Nothing runs just because it appears in this chain.</p><div class="step-footer"><span class="fine">No calculation will be started.</span><button class="primary" data-notice="Preview only. No job submitted, model changed or approval granted.">Preview run action →</button></div></section>`;
 else content=`<section class="form-card"><h2>Your study, brought together</h2><p class="muted">Results follow the analyses you selected. Unselected studies do not appear as completed checks.</p><div class="domain-list">${selectedModules().map(module=>`<div class="domain-item"><h3>${module.result}</h3>${bundledActivities(module)}<p>No recorded result connected. The product will show exact source, units, method and limitations.</p></div>`).join('')}</div><div class="state-note">No results available in this prototype. No engineering or reliability conclusion is established.</div><div class="step-footer"><button class="text-btn" data-open-chat="Summarize the selected study results using verified evidence and identify unavailable checks.">Explore results with GridSpine →</button><button class="secondary" data-notice="Native reports must use recorded evidence. No report is generated here.">Preview report →</button></div></section>`;
 const index=stageList().findIndex(step=>step.id===state.step)+1;
 return `<div class="workspace-toolbar"><button class="back-link" data-view="builder">← Edit workflow composition</button>${modePill()}</div><div class="guide-heading"><div><span class="eyebrow">CONNECTED WORKFLOW · STAGE ${index} OF ${stageList().length}</span><h1>${module?module.name+'.':stepName()+'.'}</h1><p>One model, your selected analyses, and the level of detail you need.</p></div><span class="tag">Guided</span></div><div class="guide-layout"><div>${content}</div><aside class="guide-aside"><section class="context-card"><h3>Your model</h3>${demos.some(demo=>demo.id===state.source)?`<div class="context-media">${industryPicture(demos.find(demo=>demo.id===state.source))}</div>`:art('network')}${sourceReadiness()}<p>${escapeHtml(state.caseName)}<br>Illustration · not a model readout</p></section><section class="context-card"><h3>Included in this study</h3><p class="planning-goal">${reliabilityGoalLabel()}<br><span class="fine">Objective only · not validated</span></p><ul class="check-list">${selectedModules().map(item=>`<li><span>→</span>${item.name}</li>`).join('')}</ul><button class="text-btn" data-view="builder">Change composition →</button><p class="fine">Expert and the same GridSpine companion are available at every stage.</p></section></aside></div>`;
}
function render(focusMain=false){
 ensureValidStep();if((state.view==='guided'||state.view==='expert')&&state.selected.length)state.scopes[state.source]={selected:[...state.selected],step:state.step,reliabilityAim:state.reliabilityAim};$('#sidebar').innerHTML=state.view==='home'?homeSidebar():state.view==='builder'?builderSidebar():state.view==='guided'?guidedSidebar():expertSidebar();
 $('#main').innerHTML=state.view==='home'?homeMain():state.view==='builder'?builderMain():state.view==='guided'?guidedMain():expertMain();
 if(state.view==='expert')$('#main').insertAdjacentHTML('afterbegin',sourceReadiness());
 document.querySelectorAll('[data-industry]').forEach(image=>{image.src=industryMedia[image.dataset.industry];});
 $('#header-context').innerHTML=state.view==='home'?'Your workspace <span>/</span> Overview':`${escapeHtml(state.caseName)} <span>/</span> ${state.view==='builder'?'Workflow builder':state.view==='guided'?'Guided workflow':'Expert'}`;
 $('#chat-context').textContent=state.view==='home'?'Context: workspace overview':`Context: ${state.caseName} · ${state.view==='builder'?'Workflow composition':state.view==='guided'?stepName():state.expertPanel}`;
 document.querySelectorAll('[data-section]').forEach(input=>{const section=sections.find(item=>item.id===input.dataset.section);const count=section.members.filter(id=>state.selected.includes(id)).length;input.indeterminate=count>0&&count<section.members.length;});
 document.querySelectorAll('.preview-bar [data-view]').forEach(button=>button.toggleAttribute('aria-current',button.dataset.view===state.view));if(focusMain)$('#main').focus({preventScroll:true});
}
let toastTimer;
function notice(text){$('#toast').textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('#toast').textContent='';},6500);}
function setView(view){if(view==='guided'&&!state.selected.length)view='builder';state.view=view;render(true);window.scrollTo(0,0);$('#shell').scrollTop=0;}
function chooseSource(id){state.source=id;state.caseName=demos.find(demo=>demo.id===id)?.name??'Your own model';}
function startExample(id,resume=false){chooseSource(id);const saved=resume?state.scopes[id]:null;state.selected=[...(saved?.selected??demos.find(demo=>demo.id===id).suggested)];state.step=resume?(saved?.step??state.selected[0]):'model';state.reliabilityAim=saved?.reliabilityAim??'tradeoff';setView(resume?'guided':'builder');}
function updateConversationMode(){const mode=state.companionMode;$('#companion').dataset.mode=mode;$('#mode-info').textContent={write:'Write · review your message before sending.',dictate:'Dictation preview · microphone off. The product opens reviewed dictation; nothing is captured or sent automatically.',live:'Live chat preview · text conversation. No microphone, model or backend is connected.'}[mode];document.querySelectorAll('[data-conversation-mode]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.conversationMode===mode)));}
function openChat(text){if(text)state.companionMode='write';updateConversationMode();$('#companion-actions').hidden=true;$('#chat').hidden=false;$('#companion').setAttribute('aria-expanded','true');$('#companion').setAttribute('aria-label','Close GridSpine companion');if(text)$('#message').value=text;$('#message').focus();}
function closeChat(){state.companionMode='write';updateConversationMode();$('#companion-actions').hidden=true;$('#chat').hidden=true;$('#companion').setAttribute('aria-expanded','false');$('#companion').setAttribute('aria-label','Open GridSpine companion');$('#companion').focus();}
document.addEventListener('click',event=>{
 const button=event.target.closest('button');if(!button)return;const data=button.dataset;
 if(data.view){if(data.view==='home')state.homeTab='overview';setView(data.view);}if(data.homeTab){state.homeTab=data.homeTab;setView('home');}
 if(data.generic!==undefined){chooseSource('generic');state.selected=[];state.step='model';setView('builder');}
 if(data.conversationMode){state.companionMode=data.conversationMode;openChat();}
 if(data.demo)startExample(data.demo);if(data.resume)startExample(data.resume,true);
 if(data.step){state.step=data.step;render(true);}if(data.panel){state.expertPanel=data.panel;render(true);}if(data.notice)notice(data.notice);if(data.openChat)openChat(data.openChat);
 if(button.id==='select-all'){state.selected=modules.map(module=>module.id);render();$('#select-all').focus();}
 if(button.id==='use-example-preset'){const example=demos.find(item=>item.id===state.source);if(example){state.selected=modules.filter(module=>example.suggested.includes(module.id)).map(module=>module.id);render();$('#use-example-preset').focus();}}
 if(button.id==='clear-selection'){state.selected=[];render();$('#clear-selection').focus();}
 if(button.id==='start-workflow'&&state.selected.length&&validPlanning()){ensureValidStep();setView('guided');}
 if(button.id==='companion'){if($('#chat').hidden)openChat();else closeChat();}if(button.id==='close-chat')closeChat();
 if(button.id==='theme'){state.dark=!state.dark;document.body.classList.toggle('dark',state.dark);button.innerHTML=`◐ <span>${state.dark?'Dark':'Light'}</span>`;button.setAttribute('aria-label',`Switch to ${state.dark?'light':'dark'} theme`);}
 if(button.id==='account')notice('Design preview. No account or personal data is connected.');
});
document.addEventListener('change',event=>{const target=event.target;
 if(target.dataset.module){state.selected=modules.filter(module=>module.id===target.dataset.module?target.checked:state.selected.includes(module.id)).map(module=>module.id);render();$(`[data-module="${target.dataset.module}"]`).focus();}
 if(target.dataset.section){const section=sections.find(item=>item.id===target.dataset.section);state.selected=modules.filter(module=>section.members.includes(module.id)?target.checked:state.selected.includes(module.id)).map(module=>module.id);render();$(`[data-section="${section.id}"]`).focus();}
 if(target.id==='reliability-aim'){state.reliabilityAim=target.value;}
 if(target.dataset.condition){state.conditions[state.source]??={stress:'baseline',shape:'template',annual:''};state.conditions[state.source][target.dataset.condition]=target.value;if(target.dataset.condition==='shape'){render();$('[data-condition="shape"]').focus();}}
 if(target.id==='model-source'){chooseSource(target.value);render();$('#model-source').focus();}
});
document.addEventListener('contextmenu',event=>{const example=event.target.closest('[data-demo]');if(example){event.preventDefault();startExample(example.dataset.demo);}});
document.addEventListener('input',event=>{const target=event.target;
 if(target.dataset.planning){state.planning[state.source]??={...planningDraft()};state.planning[state.source][target.dataset.planning]=target.value;const valid=validPlanning();$('#planning-error').textContent=valid?'':'Choose whole years from 1900 to 2200, with the end year at or after the start. Optional investment dates must be ordered, unique and within the period.';if($('#start-workflow'))$('#start-workflow').disabled=!valid||!state.selected.length;}
 if(target.dataset.field){const key=`${state.source}:${state.step}`;state.values[key]??={};state.values[key][target.dataset.field]=target.value;}
 if(target.id==='tool-search'){const query=target.value.trim().toLowerCase();document.querySelectorAll('.expert-nav-group').forEach(group=>{let visible=false;const name=group.querySelector('summary').textContent.toLowerCase();group.querySelectorAll('button').forEach(button=>{const matches=name.includes(query)||button.textContent.toLowerCase().includes(query);button.hidden=!matches;visible||=matches;});group.hidden=!visible;if(query)group.open=visible;});}
});
document.addEventListener('submit',event=>{event.preventDefault();
 if(event.target.id==='stage-form'){state.step=nextStage();render(true);}
 if(event.target.id==='chat-form'&&$('#message').value.trim()){const message=document.createElement('p');message.className='chat-message';message.textContent=$('#message').value.trim();$('#messages').appendChild(message);$('#message').value='';notice('Preview only. No message sent to a model and no parameters changed.');}
});
const companionControls=$('#companion-controls');
companionControls.addEventListener('mouseenter',()=>{$('#companion-actions').hidden=false;});
companionControls.addEventListener('mouseleave',()=>{if(!companionControls.contains(document.activeElement))$('#companion-actions').hidden=true;});
companionControls.addEventListener('focusin',event=>{if(!companionControls.contains(event.relatedTarget))$('#companion-actions').hidden=false;});
companionControls.addEventListener('focusout',event=>{if(!companionControls.contains(event.relatedTarget))$('#companion-actions').hidden=true;});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(!$('#chat').hidden)closeChat();else if(!$('#companion-actions').hidden){$('#companion').focus();$('#companion-actions').hidden=true;}}});
updateConversationMode();
render();
